rule.text:
@prefix app: <urn:fabry-demo:> .
@prefix obo: <http://purl.obolibrary.org/obo/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
{ ?m a app:Mechanism; app:cellType ?cell; app:location obo:UBERON_0002113 . } => { ?m a app:KidneyCellEvidenceSelectionCandidate . } .

proof.text:
@prefix app: <urn:fabry-demo:> .
@prefix obo: <http://purl.obolibrary.org/obo/> .
@prefix pe: <https://eyereasoner.github.io/pe#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .

app:renal a app:KidneyCellEvidenceSelectionCandidate .

{ app:renal a app:KidneyCellEvidenceSelectionCandidate . } pe:why {
  { app:renal a app:KidneyCellEvidenceSelectionCandidate . }
    pe:by [ pe:rule "session-program"; pe:line 4 ];
    pe:binding
      [ pe:var "cell"; pe:value obo:CL_0000653 ],
      [ pe:var "m"; pe:value app:renal ];
    pe:uses
      { app:renal a app:Mechanism . },
      { app:renal app:cellType obo:CL_0000653 . },
      { app:renal app:location obo:UBERON_0002113 . }.

  { app:renal a app:Mechanism . }
    pe:by [ pe:fact "<unknown>" ].

  { app:renal app:cellType obo:CL_0000653 . }
    pe:by [ pe:fact "<unknown>" ].

  { app:renal app:location obo:UBERON_0002113 . }
    pe:by [ pe:fact "<unknown>" ].
}.

queries.chemistry:
PREFIX up: <http://purl.uniprot.org/core/>
PREFIX taxon: <http://purl.uniprot.org/taxonomy/>
PREFIX rh: <http://rdf.rhea-db.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?protein ?reaction ?physiologicalReaction ?equation ?role ?participant ?chebi ?chemicalName
WHERE {
  VALUES ?protein { <http://purl.uniprot.org/uniprot/P06280> }
  ?protein up:organism taxon:9606; up:annotation ?annotation .
  ?annotation a up:Catalytic_Activity_Annotation;
    up:catalyticActivity/up:catalyzedReaction ?reaction;
    up:catalyzedPhysiologicalReaction ?physiologicalReaction .
  SERVICE <https://sparql.rhea-db.org/sparql> {
    VALUES (?reaction ?physiologicalReaction) { (rh:21112 rh:21113) (rh:48020 rh:48021) }
    ?reaction rh:status rh:Approved;
      rh:directionalReaction ?physiologicalReaction .
    ?physiologicalReaction rh:equation ?equation; ?role ?side .
    VALUES ?role { rh:substrates rh:products }
    ?side rh:contains ?participant .
    ?participant rh:compound ?compound .
    ?compound rh:chebi ?chebi .
    OPTIONAL { ?chebi rdfs:label ?chemicalName }
  }
}
ORDER BY ?reaction ?role ?chebi
